**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <set>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dziennik.txt");
    string nazwisko, przedmiot;
    int ocena;

    map<string, int> ilePrzedm;
    map<string, int> dobre;
    map<string, set<string>> uczenPrzedmioty;

    while (plik >> nazwisko >> przedmiot >> ocena) {
        ilePrzedm[przedmiot]++;
        if (ocena >= 4) dobre[przedmiot]++;
        uczenPrzedmioty[nazwisko].insert(przedmiot);
    }

    // a)
    cout << "a) Uczniow na przedmiot:" << endl;
    for (auto &p : ilePrzedm)
        cout << "   " << p.first << ": " << p.second << endl;

    // b)
    cout << endl << "b) Oceny >= 4 na przedmiot:" << endl;
    for (auto &p : ilePrzedm)
        cout << "   " << p.first << ": " << dobre[p.first] << endl;

    // c)
    cout << endl << "c) Procent ocen >= 4:" << endl;
    cout << fixed << setprecision(2);
    string bestPrzedm; double bestPct = 0;
    for (auto &p : ilePrzedm) {
        double pct = (double)dobre[p.first] * 100.0 / p.second;
        cout << "   " << p.first << ": " << pct << "%" << endl;
        if (pct > bestPct) {
            bestPct = pct;
            bestPrzedm = p.first;
        }
    }
    cout << "   Najwyzszy: " << bestPrzedm << " (" << bestPct << "%)" << endl;

    // d)
    int wieloPrzedm = 0;
    for (auto &p : uczenPrzedmioty)
        if ((int)p.second.size() > 1) wieloPrzedm++;
    cout << endl << "d) Uczniow w >1 przedmiocie: " << wieloPrzedm << endl;
    return 0;
}
```

**Wyjasnienie**: Trzy struktury danych: `ilePrzedm` zlicza uczniow per przedmiot, `dobre` zlicza oceny >=4 per przedmiot, `uczenPrzedmioty` mapuje ucznia na zbior jego przedmiotow. Po wczytaniu danych wykonujemy analizy.

Weryfikacja:
a) Fizyka: Wisniewski, Kowalski, Zielinska, Wojcik = 4
   Informatyka: Kaminski, Szymanski, Kowalski, Nowak = 4
   Matematyka: Kowalski, Nowak, Lewandowski, Dabrowska = 4

b) Fizyka >=4: 4, 4, 5 = 3 (Zielinska ma 2)
   Informatyka >=4: 5, 4, 4 = 3 (Kowalski ma 3)
   Matematyka >=4: 5, 4 = 2 (Nowak 3, Dabrowska 2)

c) Fizyka: 3/4*100 = 75.00%
   Informatyka: 3/4*100 = 75.00%
   Matematyka: 2/4*100 = 50.00%
   Najwyzszy: Fizyka (75.00%) — mapa iteruje alfabetycznie, Fizyka przed Informatyka

d) Kowalski: {Matematyka, Fizyka, Informatyka} = 3 > 1
   Nowak: {Matematyka, Informatyka} = 2 > 1
   Reszta: po 1 przedmiocie
   Razem: 2
